"""docs/literature.md is generated by scripts/build_literature.py; code cites sources as [key locator] comments."""
import subprocess
import sys
from pathlib import Path

REPO = Path(__file__).resolve().parents[1]


def test_register_is_current_and_code_cites_only_registered_keys():
    r = subprocess.run([sys.executable, str(REPO / "scripts" / "build_literature.py"), "--check"],
                       capture_output=True, text=True, encoding="utf-8")
    assert r.returncode == 0, r.stderr
